@app.post("/v1/chats/{chat_id}/messages", status_code=201)
async def send_message(chat_id: str, body: MessageIn,
                       authorization: Annotated[str | None, Header()] = None,
                       idempotency_key: Annotated[str | None, Header(max_length=255)] = None):
    owner = who(authorization)
    if not owner:
        return unauthorized()
    ok, remaining, reset = take_token(owner)
    if not ok:
        r = problem(429, "rate-limited", "Too many requests.", f"Retry in {reset} s.")
        r.headers.update({"Retry-After": str(reset), **rate_headers(remaining, reset)})
        return r
    if not idempotency_key:
        return problem(400, "idempotency-key-missing", "Idempotency-Key header required.",
                       "Generate a UUID per logical message and resend it on every retry.")
    req_hash = hashlib.sha256(body.model_dump_json().encode() + chat_id.encode()).hexdigest()
    # 1. claim the key atomically: the primary key makes a second insert fail
    try:
        DB.execute("insert into idempotency_keys values(?,?,?,'started',null,null,?)",
                   (owner, idempotency_key, req_hash, int(time.time())))
    except sqlite3.IntegrityError:
        status, old_hash, code, saved = DB.execute(
            "select status,request_hash,response_code,response_body from idempotency_keys where owner=? and key=?",
            (owner, idempotency_key)).fetchone()
        if old_hash != req_hash:
            return problem(422, "idempotency-key-reused", "Idempotency-Key reused with a different request.",
                           "Use a new key for a new message.")
        if status == "started":
            return problem(409, "idempotency-key-in-use", "A request with this key is still in progress.",
                           "Retry after it finishes.")
        return JSONResponse(json.loads(saved), status_code=code, headers={"Idempotent-Replayed": "true"})
    # 2. do the work once: store the message, charge credits, "call the model"
    if not DB.execute("select 1 from chats where id=? and owner=?", (chat_id, owner)).fetchone():
        DB.execute("delete from idempotency_keys where owner=? and key=?", (owner, idempotency_key))
        return problem(404, "not-found", "Chat not found.", f"No chat {chat_id} for this API key.")
    if body.stream:
        DB.execute("delete from idempotency_keys where owner=? and key=?", (owner, idempotency_key))
        return StreamingResponse(fake_stream(body.content), media_type="text/event-stream",
                                 headers={"Cache-Control": "no-cache"})
    await asyncio.sleep(float(os.environ.get("SLOW_S", "0")))         # pretend the model takes a while
    msg_id = "msg_" + uuid.uuid4().hex[:12]
    reply = "Echo: " + body.content[:40]
    # 3. one transaction: the message, the charge and the stored response commit together or not at all
    DB.execute("begin")
    DB.execute("insert into messages values(?,?,?,?,?)", (msg_id, chat_id, "assistant", reply, int(time.time())))
    DB.execute("update credits set balance = balance - 10 where owner=?", (owner,))
    out = {"id": msg_id, "chat_id": chat_id, "role": "assistant", "content": reply,
           "credits_left": DB.execute("select balance from credits where owner=?", (owner,)).fetchone()[0]}
    DB.execute("update idempotency_keys set status='done', response_code=201, response_body=? "
               "where owner=? and key=?", (json.dumps(out), owner, idempotency_key))
    DB.execute("commit")
    return JSONResponse(out, status_code=201, headers=rate_headers(remaining, reset))

